import{_ as a,o as e,c as l,ag as r}from"./chunks/framework.i8sMDeRW.js";const u=JSON.parse('{"title":"Agent 评估指标","description":"","frontmatter":{},"headers":[],"relativePath":"guide/04-evaluation/agent-evaluation-metrics.md","filePath":"guide/04-evaluation/agent-evaluation-metrics.md","lastUpdated":1778766569000}'),n={name:"guide/04-evaluation/agent-evaluation-metrics.md"};function i(d,t,o,s,h,g){return e(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="agent-评估指标" tabindex="-1">Agent 评估指标 <a class="header-anchor" href="#agent-评估指标" aria-label="Permalink to &quot;Agent 评估指标&quot;">​</a></h1><blockquote><p><strong>基准说明</strong><br> 本文档中的指标定义与基准参考值系基于行业最佳实践汇编的参考指南，<strong>并非学术基准或官方认证标准</strong>。<br> 基准参考值范围为经验值，实际表现因应用场景、模型版本、数据集分布及评估方式的不同而存在显著差异。<br> 建议读者根据自身业务场景和数据分布自行调整评估阈值，不宜直接套用本文档中的数值作为绝对标准。<br> 当引用外部 benchmark（如 AgentBench、GAIA 等）时，其数据来源和评测条件已在相应章节标注，请注意核对其原始论文或官方仓库以获取最新信息。</p></blockquote><blockquote><p>Agent 系统的全面评估需要从任务效率、工具使用、用户交互和成本等多个维度进行量化衡量。</p></blockquote><hr><h2 id="_1-任务完成率-task-completion-rate" tabindex="-1">1. 任务完成率 (Task Completion Rate) <a class="header-anchor" href="#_1-任务完成率-task-completion-rate" aria-label="Permalink to &quot;1. 任务完成率 (Task Completion Rate)&quot;">​</a></h2><h3 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>Agent 成功完成用户请求或预定义任务的比例。是衡量 Agent 系统最基本、最重要的指标。</p><h3 id="计算方法" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务完成率 = (成功完成的任务数 / 总任务数) × 100%</span></span></code></pre></div><ul><li><strong>严格完成</strong>：任务最终输出 100% 满足所有要求</li><li><strong>宽松完成</strong>：任务主要目标达成，允许部分边缘细节缺失</li><li><strong>分级评分</strong>：1-5 分制，由评估者或自动化流程判定</li></ul><h3 id="基准参考值" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务复杂度</th><th>入门水平</th><th>良好水平</th><th>优秀水平</th></tr></thead><tbody><tr><td>简单指令任务（单步）</td><td>85%</td><td>92%</td><td>98%+</td></tr><tr><td>多步骤任务（3-5步）</td><td>70%</td><td>85%</td><td>95%+</td></tr><tr><td>复杂推理任务（&gt;5步）</td><td>50%</td><td>70%</td><td>85%+</td></tr><tr><td>开放域任务（创意/分析）</td><td>40%</td><td>60%</td><td>80%+</td></tr></tbody></table><h3 id="评估工具-框架" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>AgentBench</strong>：多维度 Agent 评测基准</li><li><strong>GAIA</strong>：通用 AI 助手评测数据集</li><li><strong>WebArena / VisualWebArena</strong>：网页 Agent 任务评测</li><li><strong>SWE-bench</strong>：软件工程 Agent 评测</li><li><strong>自定义评测流水线</strong>：基于 Playwright/Selenium + LLM-as-Judge</li></ul><h3 id="实际应用案例" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：某电商平台的客服 Agent</p><ul><li>测试 1000 个客服工单（退货、退款、物流查询等）</li><li>任务完成率从 V1 的 68% 提升至 V3 的 89%</li><li>通过 Chain-of-Thought 提示和工具调用优化，复杂退货流程完成率从 45% → 82%</li></ul><hr><h2 id="_2-工具调用成功率-tool-call-success-rate" tabindex="-1">2. 工具调用成功率 (Tool Call Success Rate) <a class="header-anchor" href="#_2-工具调用成功率-tool-call-success-rate" aria-label="Permalink to &quot;2. 工具调用成功率 (Tool Call Success Rate)&quot;">​</a></h2><h3 id="定义-1" tabindex="-1">定义 <a class="header-anchor" href="#定义-1" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>Agent 在执行过程中调用外部工具（API、数据库、搜索引擎等）的总体成功比例。</p><h3 id="计算方法-1" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-1" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具调用成功率 = (成功调用的工具次数 / 总工具调用次数) × 100%</span></span></code></pre></div><ul><li>可进一步按工具类型细分（代码执行、API 调用、数据查询等）</li><li><strong>成功</strong>：工具返回有效响应，无超时/错误</li></ul><h3 id="基准参考值-1" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-1" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具类型</th><th>入门水平</th><th>良好水平</th><th>优秀水平</th></tr></thead><tbody><tr><td>信息检索（搜索/数据库）</td><td>80%</td><td>90%</td><td>97%+</td></tr><tr><td>代码执行</td><td>75%</td><td>88%</td><td>95%+</td></tr><tr><td>外部 API 调用</td><td>82%</td><td>92%</td><td>98%+</td></tr><tr><td>文件读写操作</td><td>85%</td><td>93%</td><td>97%+</td></tr></tbody></table><h3 id="评估工具-框架-1" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-1" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>ToolBench</strong>：工具使用评测基准</li><li><strong>BFCL (Berkeley Function Calling Leaderboard)</strong>：函数调用排行榜</li><li><strong>OpenAI Evals</strong>：工具调用场景的自动化测试</li><li><strong>LangSmith</strong>：追踪工具调用链，统计成功率</li></ul><h3 id="实际应用案例-1" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-1" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：数据分析 Agent 的工具调用优化</p><ul><li>初始工具调用成功率仅 72%，主要原因：参数格式错误、API 超时</li><li>引入 Schema 验证 + 重试机制后提升至 94%</li><li>针对特定 API 的 3 次重试策略使成功率从 88% → 97%</li></ul><hr><h2 id="_3-回退率-fallback-rate" tabindex="-1">3. 回退率 (Fallback Rate) <a class="header-anchor" href="#_3-回退率-fallback-rate" aria-label="Permalink to &quot;3. 回退率 (Fallback Rate)&quot;">​</a></h2><h3 id="定义-2" tabindex="-1">定义 <a class="header-anchor" href="#定义-2" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>Agent 无法直接完成任务而触发回退机制（转人工、降级应答、放弃任务）的频率。</p><h3 id="计算方法-2" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-2" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>回退率 = (触发回退的任务数 / 总任务数) × 100%</span></span></code></pre></div><ul><li><strong>硬回退</strong>：彻底转人工客服</li><li><strong>软回退</strong>：给出兜底回答（&quot;我暂时无法处理&quot;）</li><li><strong>部分回退</strong>：完成部分任务，剩余部分转人工</li></ul><h3 id="基准参考值-2" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-2" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent 类型</th><th>可接受回退率</th><th>需改进回退率</th><th>临界回退率</th></tr></thead><tbody><tr><td>客服 Agent</td><td>&lt; 15%</td><td>15-30%</td><td>&gt; 30%</td></tr><tr><td>编程 Agent</td><td>&lt; 10%</td><td>10-20%</td><td>&gt; 20%</td></tr><tr><td>个人助理 Agent</td><td>&lt; 20%</td><td>20-35%</td><td>&gt; 35%</td></tr></tbody></table><h3 id="评估工具-框架-2" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-2" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>LangSmith</strong>：监控 Agent 决策路径，标记回退事件</li><li><strong>Phoenix / Arize AI</strong>：可观测性平台，跟踪 Agent 行为边界</li><li><strong>自定义日志分析</strong>：基于 Elasticsearch/Kibana 构建回退仪表盘</li></ul><h3 id="实际应用案例-2" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-2" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：银行客服 Agent 的回退率优化</p><ul><li>原始回退率 32%，其中 60% 的回退发生在身份验证环节</li><li>引入自动化身份验证工具（对接银行 OAuth 系统），回退率降至 14%</li><li>复杂金融产品咨询仍保持 20% 回退率（合规要求转人工）</li></ul><hr><h2 id="_4-用户干预率-user-intervention-rate" tabindex="-1">4. 用户干预率 (User Intervention Rate) <a class="header-anchor" href="#_4-用户干预率-user-intervention-rate" aria-label="Permalink to &quot;4. 用户干预率 (User Intervention Rate)&quot;">​</a></h2><h3 id="定义-3" tabindex="-1">定义 <a class="header-anchor" href="#定义-3" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>用户在与 Agent 交互过程中，需要主动纠正、补充信息或介入引导的比例。</p><h3 id="计算方法-3" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-3" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户干预率 = (需要用户干预的对话数 / 总对话数) × 100%</span></span></code></pre></div><ul><li><strong>显式干预</strong>：用户明确指出 Agent 错误并提供修正</li><li><strong>隐式干预</strong>：用户重复提问、重新表述需求</li></ul><h3 id="基准参考值-3" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-3" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评估场景</th><th>优秀</th><th>良好</th><th>需改进</th></tr></thead><tbody><tr><td>简单问答</td><td>&lt; 5%</td><td>5-10%</td><td>&gt; 10%</td></tr><tr><td>多轮任务对话</td><td>&lt; 10%</td><td>10-20%</td><td>&gt; 20%</td></tr><tr><td>复杂协同创作</td><td>&lt; 15%</td><td>15-30%</td><td>&gt; 30%</td></tr></tbody></table><h3 id="评估工具-框架-3" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-3" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>人工标注平台</strong>：LabelStudio、Scale AI 标注对话轮次</li><li><strong>对话分析工具</strong>：UserLogic、Cogint AI</li><li><strong>自建埋点</strong>：前端埋点记录用户编辑/撤回/重新生成操作</li></ul><h3 id="实际应用案例-3" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-3" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：代码生成 Agent 的用户干预</p><ul><li>初期 40% 的代码生成需要用户手动修改</li><li>通过 Few-shot 示例 + 用户偏好学习，干预率降至 18%</li><li>针对 Python 代码的干预率最低（10%），Rust 代码最高（30%）</li></ul><hr><h2 id="_5-延迟分布-latency-distribution" tabindex="-1">5. 延迟分布 (Latency Distribution) <a class="header-anchor" href="#_5-延迟分布-latency-distribution" aria-label="Permalink to &quot;5. 延迟分布 (Latency Distribution)&quot;">​</a></h2><h3 id="定义-4" tabindex="-1">定义 <a class="header-anchor" href="#定义-4" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>Agent 从接收输入到生成完整输出的时间分布特性，包括 P50、P95、P99 延迟。</p><h3 id="计算方法-4" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-4" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P50 (中位数延迟) = 排序后第 50% 分位的请求延迟</span></span>
<span class="line"><span>P95 = 排序后第 95% 分位的请求延迟</span></span>
<span class="line"><span>P99 = 排序后第 99% 分位的请求延迟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>平均延迟 = 总延迟时间 / 总请求数</span></span>
<span class="line"><span>端到端延迟 = 用户输入 -&gt; Agent 首次响应 -&gt; 最终输出完成</span></span></code></pre></div><h3 id="基准参考值-4" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-4" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务类型</th><th>P50 目标</th><th>P95 目标</th><th>P99 目标</th></tr></thead><tbody><tr><td>简单问答</td><td>&lt; 2s</td><td>&lt; 5s</td><td>&lt; 10s</td></tr><tr><td>代码生成</td><td>&lt; 5s</td><td>&lt; 15s</td><td>&lt; 30s</td></tr><tr><td>多工具调用</td><td>&lt; 8s</td><td>&lt; 20s</td><td>&lt; 45s</td></tr><tr><td>长文档分析</td><td>&lt; 15s</td><td>&lt; 35s</td><td>&lt; 60s</td></tr></tbody></table><h3 id="评估工具-框架-4" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-4" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>LangFuse</strong>：LLM 可观测性，追踪延迟分布</li><li><strong>Datadog / Grafana</strong>：APM 监控，设置延迟告警</li><li><strong>Helicone</strong>：LLM 代理成本与延迟监控</li><li><strong>OpenTelemetry</strong>：端到端追踪 Agent 调用链</li></ul><h3 id="实际应用案例-4" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-4" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：金融 Agent 延迟优化</p><ul><li>初始 P95 延迟 28s（超时率 12%）</li><li>优化策略：Streaming 输出 + 工具调用并行化 + 模型量化</li><li>优化后：P50 3.2s，P95 8.5s，超时率降至 1.2%</li></ul><hr><h2 id="_6-成本-任务比-cost-per-task" tabindex="-1">6. 成本/任务比 (Cost per Task) <a class="header-anchor" href="#_6-成本-任务比-cost-per-task" aria-label="Permalink to &quot;6. 成本/任务比 (Cost per Task)&quot;">​</a></h2><h3 id="定义-5" tabindex="-1">定义 <a class="header-anchor" href="#定义-5" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>完成每个任务所消耗的经济成本，包括 LLM API 费用、工具调用费用、基础设施成本。</p><h3 id="计算方法-5" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-5" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>成本/任务 = (LLM Token 费用 + 工具调用费用 + 推理基础设施费用) / 完成任务数</span></span></code></pre></div><ul><li><strong>Token 费用</strong>：输入 Token + 输出 Token × 模型单价</li><li><strong>工具费用</strong>：外部 API（搜索、代码执行、数据查询等）</li><li><strong>基础设施</strong>：GPU 实例、向量数据库、缓存等摊销成本</li><li><strong>重试成本</strong>：失败重试带来的额外 Token 消耗</li></ul><h3 id="基准参考值-5" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-5" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent 类型</th><th>低配置</th><th>中配置</th><th>高配置</th></tr></thead><tbody><tr><td>简单问答 Agent</td><td>$0.01-0.05</td><td>$0.05-0.15</td><td>$0.15-0.50</td></tr><tr><td>编程 Agent</td><td>$0.05-0.20</td><td>$0.20-0.80</td><td>$0.80-3.00</td></tr><tr><td>多模态 Agent</td><td>$0.10-0.50</td><td>$0.50-2.00</td><td>$2.00-5.00</td></tr><tr><td>复杂 Research Agent</td><td>$0.50-2.00</td><td>$2.00-5.00</td><td>$5.00-15.00</td></tr></tbody></table><h3 id="评估工具-框架-5" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-5" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>LangSmith</strong>：追踪 Token 消耗，统计每次运行成本</li><li><strong>Helicone</strong>：实时 LLM 成本监控 + 预算告警</li><li><strong>Arize AI</strong>：成本与性能一体化监控</li><li><strong>自定义成本计算器</strong>：基于模型定价表 × Token 计数器</li></ul><h3 id="实际应用案例-5" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-5" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：企业客服 Agent 成本优化</p><ul><li>初始成本/任务 = $0.42（使用 GPT-4）</li><li>优化方案：简单问题路由到 GPT-3.5（$0.015）+ 复杂问题 GPT-4（$0.35）</li><li>混合路由后平均成本/任务降至 $0.09，同时保持 94% 任务完成率</li><li>每月 50 万任务量，年节省 $198,000</li></ul><hr><h2 id="综合评估仪表盘建议" tabindex="-1">综合评估仪表盘建议 <a class="header-anchor" href="#综合评估仪表盘建议" aria-label="Permalink to &quot;综合评估仪表盘建议&quot;">​</a></h2><h3 id="关键监控指标组合" tabindex="-1">关键监控指标组合 <a class="header-anchor" href="#关键监控指标组合" aria-label="Permalink to &quot;关键监控指标组合&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 健康度评分 = w1 × (1 - 回退率) + w2 × 任务完成率 + w3 × (1 - 用户干预率) + w4 × (1 - 延迟异常率)</span></span></code></pre></div><p>其中 w1-w4 为权重系数，根据业务场景自定义。</p><h3 id="分级评估框架" tabindex="-1">分级评估框架 <a class="header-anchor" href="#分级评估框架" aria-label="Permalink to &quot;分级评估框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>任务完成率</th><th>回退率</th><th>用户干预率</th><th>延迟 P95</th></tr></thead><tbody><tr><td>S 级</td><td>&gt; 95%</td><td>&lt; 5%</td><td>&lt; 5%</td><td>&lt; 5s</td></tr><tr><td>A 级</td><td>85-95%</td><td>5-10%</td><td>5-10%</td><td>5-15s</td></tr><tr><td>B 级</td><td>70-85%</td><td>10-20%</td><td>10-20%</td><td>15-30s</td></tr><tr><td>C 级</td><td>&lt; 70%</td><td>&gt; 20%</td><td>&gt; 20%</td><td>&gt; 30s</td></tr></tbody></table><hr><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><strong><a href="https://github.com/THUDM/AgentBench" target="_blank" rel="noreferrer">AgentBench</a></strong> - 多维度 Agent 评测框架</li><li><strong><a href="https://docs.smith.langchain.com/evaluation" target="_blank" rel="noreferrer">LangSmith Evaluation</a></strong> - LangChain 评估方案</li><li><strong><a href="https://cloud.google.com/vertex-ai/docs/agents/evaluate" target="_blank" rel="noreferrer">Google Agent Evaluation Guide</a></strong> - Google Vertex AI Agent 评估指南</li><li><strong><a href="https://docs.anthropic.com/en/docs/build-with-claude/guardrails" target="_blank" rel="noreferrer">Anthropic Claude Evaluation</a></strong> - Anthropic 安全评估实践</li><li><strong>《Evaluating AI Agents》</strong> - Prompt Engineering Institute 白皮书</li></ul>`,96)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
